package studio.jiayu.neo;
import org.json.*;
import java.util.*;
import java.util.concurrent.*;
/** Project-scoped tools, operating on a staged snapshot until final validation. */
final class LocalDevTools {
 final MainActivity a;final JSONObject original;JSONObject staged;final JSONArray calls=new JSONArray();
 LocalDevTools(MainActivity a,JSONObject project)throws Exception{this.a=a;original=project==null?null:new JSONObject(project.toString());staged=project==null?null:new JSONObject(project.toString());}
 static String instructions(boolean project){if(!project)return "本轮没有指定项目，仅可调用 search_connectors(query)、describe_connector(id,query可选,offset可选)。工具调用只返回JSON：{\"tools\":[{\"name\":\"search_connectors\",\"args\":{\"query\":\"关键词\"}}]}。每轮最多4项，最多6轮；查询完成后正常用文字回答。";return "你可以调用本地开发工具。需要工具时只返回JSON：{\"tools\":[{\"name\":\"工具名\",\"args\":{}}]}，每轮最多4个调用，总计最多6轮。工具：inspect_project；list_files；read_file(path,startLine可选,lineCount可选最多200)；search_code(query)；replace_text(path,oldText,newText，必须精确匹配一次，适合小改动)；write_files(files文件对象，暂存并校验，最终一次写入)；check_project(真正调用手机内置源码编译器)；run_preview(打开暂存代码的离线预览)；get_debug_reports；build_apk(本机编译HTML/React/TSX及已内置依赖，打包暂存快照)。工具只能操作当前指定项目。小范围改动优先replace_text，避免重写整份文件。错误应修复再检查，不编造检查结果；无任意shell、npm联网安装或原生Gradle编译。结束时返回原定严格JSON files对象；暂存文件会与最终files合并。";}
 JSONObject call(String name,JSONObject args)throws Exception{
  if(name.equals("search_connectors"))return a.connectors.search(args.optString("query"));if(name.equals("describe_connector"))return a.connectors.describe(args.getString("id"),args.optString("query"),args.optInt("offset"));if(staged==null)throw new Exception("请先选择目标项目才能使用开发工具");
  JSONObject files=staged.getJSONObject("files"),out=new JSONObject();
  switch(name){
   case "inspect_project":out.put("name",staged.optString("name")).put("fileCount",files.length()).put("cloudSource",staged.optBoolean("cloudSource")).put("packageJson",files.optString("package.json","")).put("environment","离线 HTML/CSS/JS、TS/TSX/JSX 编译、React 与预装依赖、Tailwind 3；WebView隔离运行。原生Android/Node服务端/npm安装需外部环境。工具可以读写、搜索、检查、预览、离线打包和取回日志。");break;
   case "list_files":JSONArray names=new JSONArray();for(Iterator<String> it=files.keys();it.hasNext();){String n=it.next();names.put(new JSONObject().put("path",n).put("characters",files.getString(n).length()));}out.put("files",names);break;
   case "read_file":String path=args.getString("path");if(!files.has(path))throw new Exception("文件不存在");String[] lines=files.getString(path).split("\\n",-1);int start=Math.max(1,args.optInt("startLine",1)),count=Math.max(1,Math.min(200,args.optInt("lineCount",100)));StringBuilder text=new StringBuilder();for(int i=start-1;i<Math.min(lines.length,start-1+count);i++){if(text.length()>20000)break;text.append(i+1).append(": ").append(lines[i]).append('\n');}out.put("path",path).put("totalLines",lines.length).put("content",text.toString());break;
   case "search_code":String q=args.getString("query");if(q.isEmpty()||q.length()>200)throw new Exception("搜索词需为1到200字符");JSONArray matches=new JSONArray();for(Iterator<String> it=files.keys();it.hasNext()&&matches.length()<50;){String n=it.next();String[] code=files.getString(n).split("\\n");for(int i=0;i<code.length&&matches.length()<50;i++)if(code[i].contains(q))matches.put(new JSONObject().put("path",n).put("line",i+1).put("text",code[i].substring(0,Math.min(400,code[i].length()))));}out.put("matches",matches);break;
   case "replace_text":String editPath=args.getString("path"),oldText=args.getString("oldText"),newText=args.getString("newText");if(!files.has(editPath)||oldText.isEmpty()||oldText.length()>20000||newText.length()>20000)throw new Exception("无效的精确替换参数");String current=files.getString(editPath);int at=current.indexOf(oldText);if(at<0||current.indexOf(oldText,at+1)>=0)throw new Exception("替换片段必须在当前文件中精确匹配一次，请先读取并扩大上下文");String replaced=current.substring(0,at)+newText+current.substring(at+oldText.length());staged=ProjectEdits.apply(staged,files,new JSONObject().put(editPath,replaced),"AI 暂存");out.put("staged",true).put("path",editPath).put("replacements",1);break;
   case "write_files":staged=ProjectEdits.apply(staged,files,args.getJSONObject("files"),"AI 暂存");out.put("staged",true).put("message","暂存文件已校验，最终成功后写回项目");break;
   case "check_project":return LocalCompiler.check(a,staged);
   case "run_preview":CountDownLatch opened=new CountDownLatch(1);String[] failure={null};a.runOnUiThread(()->{try{if(a.localRunner!=null&&a.localRunner.dialog!=null)a.localRunner.dialog.dismiss();a.localRunner=new LocalRunner(a,staged);a.localRunner.start();}catch(Exception e){failure[0]=e.getMessage();}finally{opened.countDown();}});if(!opened.await(10,TimeUnit.SECONDS))throw new Exception("预览打开超时");if(failure[0]!=null)throw new Exception(failure[0]);out.put("opened",true).put("message","已打开离线预览，编译/运行日志可用get_debug_reports读取；打开不代表交互验收通过");break;
   case "get_debug_reports":synchronized(a){out.put("reports",a.byId("projects",staged.getString("id")).optJSONArray("debugReports"));}if(a.localRunner!=null&&a.localRunner.projectId.equals(staged.getString("id")))out.put("preview",a.localRunner.report());break;
   case "build_apk":CloudFiles.entries(staged);int number;synchronized(a){number=a.byId("projects",staged.getString("id")).optInt("buildNumber",0)+1;}JSONObject build=OfflineBuilder.build(a,staged,number);build.put("stagedSnapshot",true);synchronized(a){JSONObject p=a.byId("projects",staged.getString("id"));JSONArray builds=p.optJSONArray("builds");if(builds==null){builds=new JSONArray();p.put("builds",builds);}builds.put(build);p.put("buildNumber",number);a.saveState();}return new JSONObject().put("build",build).put("message","暂存快照APK已构建；未自动安装，未代表实际运行通过");
   default:throw new Exception("不支持的工具："+name);
  }return out;
 }
 JSONObject finalChanges(JSONObject changes)throws Exception{JSONObject next=ProjectEdits.apply(staged,staged.getJSONObject("files"),changes,"AI 暂存").getJSONObject("files"),old=original.getJSONObject("files"),out=new JSONObject();for(Iterator<String> it=next.keys();it.hasNext();){String n=it.next();if(!next.getString(n).equals(old.optString(n,null)))out.put(n,next.getString(n));}for(Iterator<String>it=old.keys();it.hasNext();){String n=it.next();if(!next.has(n))out.put(n,JSONObject.NULL);}return out;}
}
